import Foundation
import Testing
@testable import SlumpyCore // replace with the logic package module name

@Suite("DailyProgress.minutesToday")
struct DailyProgressTests {
    // Fixed time zone so results do not depend on the machine running the tests.
    let calendar = makeCalendar("Europe/Moscow")

    @Test func noSessionsGivesZero() {
        let now = at(28, 12, in: calendar)

        #expect(DailyProgress.minutesToday([], now: now, calendar: calendar) == 0)
    }

    @Test func sumsAllSessionsStartedToday() {
        let now = at(28, 21, in: calendar)
        let sessions = [
            session(at(28, 8, in: calendar), seconds: 10 * 60),
            session(at(28, 13, in: calendar), seconds: 15 * 60),
            session(at(28, 20, in: calendar), seconds: 5 * 60),
        ]

        #expect(DailyProgress.minutesToday(sessions, now: now, calendar: calendar) == 30)
    }

    @Test func ignoresSessionsFromOtherDays() {
        let now = at(28, 12, in: calendar)
        let sessions = [
            session(at(27, 23, in: calendar), seconds: 40 * 60),
            session(at(28, 9, in: calendar), seconds: 20 * 60),
            session(at(29, 0, 10, in: calendar), seconds: 50 * 60),
        ]

        #expect(DailyProgress.minutesToday(sessions, now: now, calendar: calendar) == 20)
    }

    @Test func dayStartsExactlyAtMidnight() {
        let now = at(28, 12, in: calendar)
        let sessions = [
            session(at(27, 23, 59, 59, in: calendar), seconds: 11 * 60),
            session(at(28, 0, 0, 0, in: calendar), seconds: 7 * 60),
            session(at(28, 23, 59, 59, in: calendar), seconds: 3 * 60),
        ]

        #expect(DailyProgress.minutesToday(sessions, now: now, calendar: calendar) == 10)
    }

    @Test func sessionCrossingMidnightCountsFullyForTheDayItStarted() {
        let crossing = session(at(27, 23, 50, in: calendar), seconds: 30 * 60)

        let nextMorning = at(28, 9, in: calendar)
        #expect(DailyProgress.minutesToday([crossing], now: nextMorning, calendar: calendar) == 0)

        let sameEvening = at(27, 23, 59, in: calendar)
        #expect(DailyProgress.minutesToday([crossing], now: sameEvening, calendar: calendar) == 30)
    }

    @Test func dayBoundaryFollowsTheGivenCalendarsTimeZone() {
        // 22:30 UTC on Oct 27 is 01:30 on Oct 28 in Moscow (UTC+3).
        let utc = makeCalendar("UTC")
        let moscow = makeCalendar("Europe/Moscow")
        let sessions = [session(at(27, 22, 30, in: utc), seconds: 25 * 60)]
        let now = at(28, 8, in: utc)

        #expect(DailyProgress.minutesToday(sessions, now: now, calendar: moscow) == 25)
        #expect(DailyProgress.minutesToday(sessions, now: now, calendar: utc) == 0)
    }

    @Test func sumsSecondsBeforeConvertingToMinutes() {
        let now = at(28, 12, in: calendar)
        let sessions = [
            session(at(28, 8, in: calendar), seconds: 40),
            session(at(28, 9, in: calendar), seconds: 40),
            session(at(28, 10, in: calendar), seconds: 40),
        ]

        // 120 s total; rounding each session down first would give 0.
        #expect(DailyProgress.minutesToday(sessions, now: now, calendar: calendar) == 2)
    }

    @Test(arguments: zip([0.0, 59, 60, 119, 3599], [0, 0, 1, 1, 59]))
    func partialMinutesAreRoundedDown(seconds: TimeInterval, expectedMinutes: Int) {
        let now = at(28, 12, in: calendar)
        let sessions = [session(at(28, 8, in: calendar), seconds: seconds)]

        #expect(DailyProgress.minutesToday(sessions, now: now, calendar: calendar) == expectedMinutes)
