import Foundation
import Testing
@testable import SlumpyKit

@Suite("DailyProgress.minutesToday")
struct DailyProgressTests {
    private let moscow = Self.calendar("Europe/Moscow")
    private let utc = Self.calendar("UTC")

    // MARK: - Basic counting

    @Test func noSessionsGivesZero() {
        let now = date(28, 12, in: moscow)

        #expect(DailyProgress.minutesToday([], now: now, calendar: moscow) == 0)
    }

    @Test func sumsAllSessionsStartedToday() {
        let now = date(28, 22, in: moscow)
        let sessions = [
            session(date(28, 8, in: moscow), seconds: 10 * 60),
            session(date(28, 21, in: moscow), seconds: 25 * 60),
        ]

        #expect(DailyProgress.minutesToday(sessions, now: now, calendar: moscow) == 35)
    }

    @Test func ignoresSessionsFromOtherDays() {
        let now = date(28, 12, in: moscow)
        let sessions = [
            session(date(27, 23, 59, 59, in: moscow), seconds: 60 * 60),
            session(date(28, 12, in: moscow), seconds: 5 * 60),
            session(date(29, 0, in: moscow), seconds: 60 * 60),
        ]

        #expect(DailyProgress.minutesToday(sessions, now: now, calendar: moscow) == 5)
    }

    // MARK: - Day boundaries

    @Test(arguments: [(0, 0, 0), (23, 59, 59)])
    func countsSessionAtEdgeOfToday(hour: Int, minute: Int, second: Int) {
        let now = date(28, 12, in: moscow)
        let sessions = [session(date(28, hour, minute, second, in: moscow), seconds: 15 * 60)]

        #expect(DailyProgress.minutesToday(sessions, now: now, calendar: moscow) == 15)
    }

    @Test func usesCalendarDayNotLast24Hours() {
        let now = date(28, 0, 30, in: moscow)
        let sessions = [session(date(27, 23, 0, in: moscow), seconds: 20 * 60)]

        #expect(DailyProgress.minutesToday(sessions, now: now, calendar: moscow) == 0)
    }

    // Pins current behavior: a session is attributed entirely to the day it started.
    @Test func sessionRunningPastMidnightCountsTowardStartDay() {
        let now = date(28, 0, 30, in: moscow)
        let sessions = [session(date(27, 23, 50, in: moscow), seconds: 30 * 60)]

        #expect(DailyProgress.minutesToday(sessions, now: now, calendar: moscow) == 0)
    }

    // MARK: - Rounding

    @Test(arguments: [
        ([59.0], 0),
        ([60.0], 1),
        ([119.0], 1),           // truncates, does not round
        ([40.0, 40.0, 40.0], 2), // truncates the total, not each session
    ])
    func truncatesTotalSecondsToWholeMinutes(durations: [TimeInterval], expected: Int) {
        let now = date(28, 23, in: moscow)
        let sessions = durations.enumerated().map { index, seconds in
            session(date(28, 10 + index, in: moscow), seconds: seconds)
        }

        #expect(DailyProgress.minutesToday(sessions, now: now, calendar: moscow) == expected)
    }

    // MARK: - Calendar

    @Test func dayIsDecidedByGivenCalendarTimeZone() {
        // 22:30 UTC on Oct 28 is 01:30 on Oct 29 in Moscow.
        let start = date(28, 22, 30, in: utc)
        let now = date(28, 12, in: utc)
        let sessions = [session(start, seconds: 10 * 60)]

        #expect(DailyProgress.minutesToday(sessions, now: now, calendar: utc) == 10)
        #expect(DailyProgress.minutesToday(sessions, now: now, calendar: moscow) == 0)
    }

    // MARK: - Helpers

    private static func calendar(_ timeZoneID: String) -> Calendar {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: timeZoneID)!
        return calendar
    }

    private func date(
        _ day: Int, _ hour: Int, _ minute: Int = 0, _ second: Int = 0,
        in calendar: Calendar
    ) -> Date {
        calendar.date(from: DateComponents(
            year: 2026, month: 10, day: day, hour: hour, minute: minute, second: second
        ))!
    }

    private func session(_ startedAt: Date, seconds: TimeInterval) -> ReadingSession {
        ReadingSession(startedAt: startedAt, duration: seconds)
    }
}
```

Каждый тест ловит конкретную поломку:
- **`truncatesTotalSecondsToWholeMinutes`:** падает, если минуты начнут округлять (119 с станут 2 минутами) или отбрасывать остаток у каждой сессии отдельно (три сессии по 40 с дадут 0 вместо 2).
- **`usesCalendarDayNotLast24Hours`:** падает, если «сегодня» заменить на «последние 24 часа».
- **`dayIsDecidedByGivenCalendarTimeZone`:** падает, если вместо переданного календаря использовать `Calendar.current`. Одна из двух проверок не пройдёт в любом часовом поясе машины.
- **`countsSessionAtEdgeOfToday`:** проверяет, что сессии в 00:00:00 и 23:59:59 считаются сегодняшними.

Сейчас сессия засчитывается целиком в тот день, когда началась. Например, чтение с 23:50 до 00:20 к утру даст 0 минут за новый день. Тест `sessionRunningPastMidnightCountsTowardStartDay` закрепляет именно это. Если по продукту такие сессии нужно делить по дням, этот тест придётся поменять вместе с функцией.
